function streak(id){let n=0,d=new Date(today()+'T12:00:00');if(!(state.logs[today()]||[]).includes(id))d.setDate(d.getDate()-1);for(let i=0;i<10000;i++){const k=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;if(!(state.logs[k]||[]).includes(id))break;n++;d.setDate(d.getDate()-1)}return n}
function render(){const checked=state.logs[state.date]||[];$('#app').innerHTML=`<div class="stats">${stat('所选日已完成',checked.length)}${stat('习惯数量',state.habits.length)}${stat('有记录的天数',Object.values(state.logs).filter(x=>x.length).length)}</div><div class="grid"><div>${panel('小行动，也值得被看见',`<label>查看 / 补记日期<input id="date" type="date" max="${today()}" value="${state.date}"></label>${state.habits.map(x=>`<div class="item"><div><h3>${x.icon} ${esc(x.name)}</h3><p>截至今天或昨天连续 ${streak(x.id)} 天 · ${esc(x.reminder)}</p></div><button data-action="${x.id}" class="${checked.includes(x.id)?'selected':''}">${checked.includes(x.id)?'已打卡 ↶':'打卡'}</button></div>`).join('')}`)}${panel('设计一个做得到的习惯',`<form id="habit" class="stack">${field('小习惯名称','name','text','','required maxlength="40"')}${field('提醒线索，例如晚饭后','reminder','text','','required maxlength="60"')}<button>添加我的习惯</button></form>`)}</div><div>${panel('今天的挑战进度',`${progress(checked.length/state.habits.length*100)}<p>${checked.length===state.habits.length?'全部完成！想一想哪个提醒最有用。':'不用追求完美。选一个现在能做到的小行动。'}</p><p class="notice">提醒仅显示在此页面，不会推送通知。连续记录允许今天尚未打卡；断一天后重新计算。</p>`,'tint')}${panel('最近的行动',Object.entries(state.logs).filter(([,v])=>v.length).sort((a,b)=>b[0].localeCompare(a[0])).slice(0,7).map(([d,v])=>`<div class="item"><strong>${d}</strong><span>${v.length} 项完成</span></div>`).join('')||empty())}</div></div>`;
$('#date').onchange=e=>{if(!e.target.value||e.target.value>today())return toast('请选择今天或之前的日期');state.date=e.target.value;commit()};actions('[data-action]',id=>{let list=state.logs[state.date]||[];state.logs[state.date]=list.includes(id)?list.filter(x=>x!==id):[...list,id];commit()});form('habit',v=>{if(state.habits.some(x=>x.name===v.name))return toast('这个习惯已经在列表里');state.habits.push({...v,id:uid(),icon:'🌱'});commit()})}if(!state.date)state.date=today();render();
